#!/usr/bin/env ruby
# frozen_string_literal: true

# Generates a deterministic, sharded eCHIS household/CHW dataset whose shape
# follows the eCHIS dev server (https://echisv3.intellisoftkenya.com/fhir):
# households are Groups of Patients managed by a CHV PractitionerRole inside
# a Kenya administrative Location hierarchy, every patient-data resource
# carries the dev server's supervision-location sync tag, and care happens
# through the server's own Questionnaires -- each visit is a
# QuestionnaireResponse generated by walking the real form (enableWhen
# honoured), with Observations extracted exactly where the form marks items
# observation-extract, plus the DetectedIssue/Task/Condition records the
# decision-support PlanDefinitions imply. See docs/echis-data-model.md.
#
# The reference content (Questionnaires, PlanDefinitions, ActivityDefinitions,
# country/county Locations) is a snapshot taken by
# scripts/snapshot_echis_content.rb and is PUT before any household data.

require "date"
require "fileutils"
require "json"
require "net/http"
require "openssl"
require "optparse"
require "set"
require "time"
require "uri"
require "zlib"

# When stdout isn't a real terminal (piped through `scripts/lab`, captured
# by the Lab Control UI's child_process spawn into a log file/SSE stream --
# the normal case), Ruby fully buffers writes instead of line-buffering
# them. Progress output then sits invisible in the process's internal
# buffer for however long it takes to fill (observed live: tens of minutes
# of real progress with zero new log lines, confirmed lagging by ~12
# percentage points against the FHIR server's own resource count) rather
# than appearing as it happens. Forcing sync mode makes every `puts`/`print`
# flush immediately regardless of TTY-ness, which is what "live progress"
# actually requires.
$stdout.sync = true

class SeedError < StandardError; end

DEFAULT_CONTENT_PATH = File.expand_path("../benchmarks/echis/content/echis-content.json", __dir__)

options = {
  individuals_per_household: 3,
  batch_size: 100,
  timeout: 120,
  shard_index: 0,
  shard_count: 1,
  metadata_only: false,
  include_specimen: false,
  content: DEFAULT_CONTENT_PATH,
  max_retries: 3
}

OptionParser.new do |opts|
  opts.banner = "Usage: scripts/echis_seed.rb --households N --seed S --run-id RUN_ID --metadata FILE [--fhir-base-url URL | --metadata-only]"
  opts.on("--households N", Integer, "Total household count across all shards (not this shard's own slice) -- combined with --shard-index/--shard-count to compute this invocation's [start_index, end_index) range.") { |v| options[:households] = v }
  opts.on("--individuals-per-household N", Integer, "Average individuals per household; default 3. Household sizes cycle N, N+1, N-1 when N >= 2.") { |v| options[:individuals_per_household] = v }
  opts.on("--seed S", Integer, "Deterministic seed; drives demographics, visit mix, and form answers.") { |v| options[:seed] = v }
  opts.on("--run-id RUN_ID", "Run identifier.") { |v| options[:run_id] = v }
  opts.on("--metadata FILE", "Dataset metadata JSON file to write.") { |v| options[:metadata] = v }
  opts.on("--fhir-base-url URL", "FHIR base URL that accepts transaction bundle POSTs. Required unless --metadata-only.") { |v| options[:fhir_base_url] = v }
  opts.on("--content FILE", "Reference content snapshot (.json or .json.gz) from scripts/snapshot_echis_content.rb; default benchmarks/echis/content/echis-content.json.") { |v| options[:content] = v }
  opts.on("--batch-size N", Integer, "Households per transaction bundle; default 100.") { |v| options[:batch_size] = v }
  opts.on("--timeout SECONDS", Integer, "HTTP open/read timeout in seconds; default 120.") { |v| options[:timeout] = v }
  opts.on("--max-retries N", Integer, "Retries per transaction bundle on network errors or HTTP 409/412/429/5xx; default 3. Safe because every entry is an idempotent PUT.") { |v| options[:max_retries] = v }
  opts.on("--shard-index N", Integer, "This invocation's shard number (0-based); default 0.") { |v| options[:shard_index] = v }
  opts.on("--shard-count N", Integer, "Total number of shards; default 1.") { |v| options[:shard_count] = v }
  opts.on("--metadata-only", "Compute and record dataset metadata without making HTTP calls.") { options[:metadata_only] = true }
  opts.on("--include-specimen", "Emit a blood Specimen for every malaria rapid test taken during an under-5 assessment; off by default.") { options[:include_specimen] = true }
  opts.on("-h", "--help", "Show this help.") do
    puts opts
    exit
  end
end.parse!

# --- Systems and URLs, copied verbatim from the eCHIS dev server -------------

