HOUSEHOLD_IDENTIFIER_SYSTEM = "urn:demo:household"
PATIENT_IDENTIFIER_SYSTEM = "urn:demo:patient"
PRACTITIONER_IDENTIFIER_SYSTEM = "http://hl7.org/fhir/administrative-identifier"
PRACTITIONER_LOCATION_EXTENSION = "http://example.org/location"
PRACTITIONER_ROLE_GROUP_EXTENSION = "http://example.org/fhir/StructureDefinition/role-group"
NPHIIS_ROLE_SYSTEM = "https://nphiis.health.go.ke/fhir/CodeSystem/nphiis-roles"
ROLE_CODE_SYSTEM = "http://terminology.hl7.org/CodeSystem/v3-RoleCode"
ACT_CODE_SYSTEM = "http://terminology.hl7.org/CodeSystem/v3-ActCode"
INSTANTIATES_PLAN_DEFINITION_EXTENSION = "http://icl.ohs.echis.reference/fhir/StructureDefinition/instantiates-plan-definition"
OBSERVATION_EXTRACT_EXTENSION = "http://icl.ohs.echis.reference/fhir/StructureDefinition/observation-extract"
