# Every date in the dataset is relative to this fixed day, never the clock,
# so a re-run of any shard reproduces byte-identical resources.
REFERENCE_DATE = Date.new(2026, 9, 1)

# --- Catchment hierarchy -------------------------------------------------------
#
# Sized to Kenya's community health strategy: one CHV (Community Health
# Promoter) per 100 households, ten CHVs and one CHA per Community Health
# Unit (~1,000 households). At the 10M-household peak tier this yields 100k
# CHVs, 10k CHUs, 5k link facilities, ~1.7k wards and ~333 sub-counties --
# close to Kenya's real ~1,450 wards and ~300 sub-counties. Every index is
# pure integer division from the GLOBAL household index, so every shard
# computes identical hierarchy ids with no coordination. Sub-counties are
# spread round-robin across the snapshot's 47 real counties.
CHW_CATCHMENT_SIZE = 100
CHVS_PER_UNIT = 10
UNITS_PER_FACILITY = 2
FACILITIES_PER_WARD = 3
WARDS_PER_SUB_COUNTY = 5

def chw_index_for(household_index) = household_index / CHW_CATCHMENT_SIZE
def unit_index_for(chw_index) = chw_index / CHVS_PER_UNIT
def facility_index_for(unit_index) = unit_index / UNITS_PER_FACILITY
def ward_index_for(facility_index) = facility_index / FACILITIES_PER_WARD
def sub_county_index_for(ward_index) = ward_index / WARDS_PER_SUB_COUNTY

# Household sizes cycle N, N+1, N-1 around the requested average, so the
# roster varies like the dev server's (1-5 members) while individual indices
# stay contiguous and computable in O(1) from the household index alone.
HOUSEHOLD_SIZE_OFFSETS = [0, 1, -1].freeze

def household_size(household_index, individuals_per_household)
  return individuals_per_household if individuals_per_household < 2

  individuals_per_household + HOUSEHOLD_SIZE_OFFSETS[household_index % 3]
end

def first_individual_index(household_index, individuals_per_household)
  return household_index * individuals_per_household if individuals_per_household < 2

  (household_index * individuals_per_household) + (household_index % 3 == 2 ? 1 : 0)
end

def total_individuals(households, individuals_per_household)
  first_individual_index(households, individuals_per_household)
end

# --- Deterministic randomness --------------------------------------------------
#
# SplitMix64 keyed on (seed, stream, salt). Each person/household/visit gets
# its own stream, so a shard never depends on what another shard drew, and
# Zlib.crc32 (not String#hash, which Ruby randomizes per process) turns salts
# into stable integers.
MASK64 = (1 << 64) - 1

def mix64(value)
  value = (value + 0x9E3779B97F4A7C15) & MASK64
  value = ((value ^ (value >> 30)) * 0xBF58476D1CE4E5B9) & MASK64
  value = ((value ^ (value >> 27)) * 0x94D049BB133111EB) & MASK64
  value ^ (value >> 31)
end

class Draw
  def initialize(seed, stream, salt)
    @state = mix64(mix64(seed & MASK64) ^ mix64((stream & MASK64) ^ Zlib.crc32(salt.to_s)))
  end

  def next_u64
    @state = (@state + 0x9E3779B97F4A7C15) & MASK64
    mix64(@state)
  end

  def float = (next_u64 >> 11).fdiv(1 << 53)
  def chance?(probability) = float < probability
  def int(min, max) = min + (next_u64 % (max - min + 1))
  def pick(values) = values[next_u64 % values.length]

  def weighted(pairs)
    total = pairs.sum { |_, weight| weight }
    target = float * total
    pairs.each do |value, weight|
      target -= weight
      return value if target < 0
    end
    pairs.last.first
  end
end

