FEMALE_GIVEN_NAMES = %w[
  Wanjiku Akinyi Chepkoech Achieng Njeri Atieno Wambui Nafula Moraa Kerubo Nyambura Jepkemoi
  Mumbua Zawadi Halima Amina Grace Faith Mercy Esther Joan Anita Lydia Naliaka Chemutai Asha
].freeze
MALE_GIVEN_NAMES = %w[
  Otieno Kiprotich Mwangi Kamau Ochieng Wafula Kipngeno Mutua Omondi Njoroge Barasa Kibet
  Hassan Juma Samuel Peter John Brian Kevin David Ethan Joseph Daniel Emmanuel Kiplagat Musa
].freeze
FAMILY_NAMES = %w[
  Langat Kipkorir Otieno Mwangi Kamau Wanjala Odhiambo Kiptoo Mutua Njoroge Barasa Chege
  Onyango Wekesa Kariuki Rotich Cheruiyot Owino Ndirangu Mohamed Ali Nyaga Muriuki Ouma
].freeze

def given_names(draw, gender)
  pool = gender == "female" ? FEMALE_GIVEN_NAMES : MALE_GIVEN_NAMES
  first = draw.pick(pool)
  second = draw.pick(pool)
  second = pool[(pool.index(second) + 1) % pool.length] if second == first
  [first, second]
end

def phone_number(draw) = format("07%08d", draw.int(0, 99_999_999))

# --- Reference content ---------------------------------------------------------

REQUIRED_QUESTIONNAIRES = %w[
  household-registration under-5-assessment-service-questionnaire immunization-service-questionnaire
  defaulter-follow-up-questionnaire pregnancy-screening-registration-questionnaire
  pregnancy-home-service-questionnaire mother-newborn-pnc-home-service-questionnaire
  diabetes-service-questionnaire tb-service-questionnaire referral-follow-up-questionnaire
  death-report-questionnaire
].freeze

class Content
  attr_reader :resources, :counties, :country

  def initialize(resources)
    @resources = resources
    @questionnaires = resources.select { |r| r["resourceType"] == "Questionnaire" }.to_h { |r| [r["id"], r] }
    @plan_definitions = resources.select { |r| r["resourceType"] == "PlanDefinition" }.to_h { |r| [r["id"], r] }
    locations = resources.select { |r| r["resourceType"] == "Location" }
    @country = locations.find { |location| Content.level(location) == "country" }
    @counties = locations.select { |location| Content.level(location) == "county" }.sort_by { |county| Content.county_code(county) }

    missing = REQUIRED_QUESTIONNAIRES.reject { |id| @questionnaires.key?(id) }
    raise SeedError, "content snapshot is missing Questionnaire(s): #{missing.join(", ")}" unless missing.empty?
    raise SeedError, "content snapshot has no county Locations" if @counties.empty?
  end

  def self.level(location)
    Array(location["type"]).flat_map { |type| Array(type["coding"]) }
      .find { |coding| coding["system"] == ADMINISTRATIVE_LEVEL_SYSTEM }&.fetch("code", nil)
  end

  def self.county_code(county)
    Array(county["identifier"]).find { |identifier| identifier["system"] == COUNTY_IDENTIFIER_SYSTEM }&.fetch("value", nil) || county["name"].to_s
  end

  def questionnaire(id) = @questionnaires.fetch(id)
  def plan_title(id) = @plan_definitions.dig(id, "title") || id
end

def load_content(path)
  raise SeedError, "content snapshot not found: #{path} (create it with scripts/snapshot_echis_content.rb)" unless File.file?(path)

  raw = path.end_with?(".gz") ? Zlib::GzipReader.open(path, &:read) : File.read(path)
  resources = Array(JSON.parse(raw)["entry"]).map { |entry| entry["resource"] }.compact
  raise SeedError, "content snapshot #{path} contains no resources" if resources.empty?

  Content.new(resources)
rescue JSON::ParserError, Zlib::Error => e
  raise SeedError, "content snapshot #{path} could not be read: #{e.message}"
end

# --- HTTP ----------------------------------------------------------------------

RETRYABLE_HTTP_CODES = [409, 412, 429, 500, 502, 503, 504].freeze

def status_success?(status)
  code = status.to_s.split(/\s+/, 2).first.to_i
  code >= 200 && code < 400
end

def post_bundle(uri, bundle, timeout)
  http = Net::HTTP.new(uri.host, uri.port)
  http.use_ssl = uri.scheme == "https"
  http.open_timeout = timeout
  http.read_timeout = timeout

  request = Net::HTTP::Post.new(uri.request_uri.empty? ? "/" : uri.request_uri)
  request["Accept"] = "application/fhir+json"
  request["Content-Type"] = "application/fhir+json"
  request.body = JSON.generate(bundle)

  http.request(request)
end

# Shards PUT the same reference content and boundary-straddling catchment
# resources concurrently, which HAPI can reject with a version conflict or a
# unique-constraint 500 when two creates race. Every entry is an idempotent
# PUT of identical content, so replaying the whole bundle is safe.
def post_bundle_with_retries(uri, bundle, timeout, max_retries)
  attempt = 0
  loop do
    begin
      response = post_bundle(uri, bundle, timeout)
      return response unless RETRYABLE_HTTP_CODES.include?(response.code.to_i) && attempt < max_retries
    rescue IOError, SystemCallError, Timeout::Error, OpenSSL::SSL::SSLError, Net::HTTPBadResponse
      raise if attempt >= max_retries
    end
    attempt += 1
    sleep([2**attempt, 30].min)
  end
end

def response_entries(response_body)
  parsed = JSON.parse(response_body)
  return [] unless parsed.is_a?(Hash) && parsed["resourceType"] == "Bundle"

  Array(parsed["entry"])
rescue JSON::ParserError
  []
end

def put_entry(resource)
  {
    "resource" => resource,
    "request" => { "method" => "PUT", "url" => "#{resource["resourceType"]}/#{resource["id"]}" }
  }
end

# --- Resource ids ----------------------------------------------------------------

def household_id(household_index) = format("echis-hh%08d", household_index)
def patient_id(individual_index) = format("echis-p%08d", individual_index)
def related_person_id(individual_index) = format("echis-rp%08d", individual_index)
def chw_practitioner_role_id(chw_index) = format("echis-chw%06d", chw_index)
def practitioner_id(chw_index) = format("echis-pr%06d", chw_index)
def care_team_id(chw_index) = format("echis-ct%06d", chw_index)
def cha_practitioner_role_id(unit_index) = format("echis-cha%06d", unit_index)
def cha_practitioner_id(unit_index) = format("echis-pr-cha%06d", unit_index)
def unit_location_id(unit_index) = format("echis-loc-chu%06d", unit_index)
def facility_location_id(facility_index) = format("echis-loc-fac%06d", facility_index)
def ward_location_id(ward_index) = format("echis-loc-ward%06d", ward_index)
def sub_county_location_id(sub_county_index) = format("echis-loc-sub%06d", sub_county_index)
def organization_id = "echis-org000001"
def visit_resource_id(kind, slug, individual_index, suffix = nil)
  base = format("echis-%s-%s%08d", kind, slug, individual_index)
  suffix.nil? ? base : format("%s-%02d", base, suffix)
end

# --- Small builders ------------------------------------------------------------

def reference(type, id, display = nil)
  ref = { "reference" => "#{type}/#{id}" }
  ref["display"] = display if display
  ref
end

def sync_tag(unit_id) = { "tag" => [{ "system" => SUPERVISION_LOCATION_TAG_SYSTEM, "code" => unit_id }] }
def plan_definition_extension(plan_definition_id) = { "url" => INSTANTIATES_PLAN_DEFINITION_EXTENSION, "valueCanonical" => "PlanDefinition/#{plan_definition_id}" }
def role_coding(code) = { "system" => NPHIIS_ROLE_SYSTEM, "code" => code, "display" => code }
def timestamp(time) = time.utc.strftime("%Y-%m-%dT%H:%M:%SZ")
def day_time(date, minutes_after_seven) = Time.utc(date.year, date.month, date.day, 7, 0, 0) + (minutes_after_seven * 60)
def full_name(person) = "#{person.given.join(" ")} #{person.family}"
def county_short_name(county) = county["name"].to_s.sub(/\s+County\z/, "")

# --- Catchment (Location hierarchy + staff) --------------------------------------

Catchment = Struct.new(
  :unit_index, :unit_id, :unit_name, :facility_id, :facility_name, :ward_id, :ward_name,
  :sub_county_id, :sub_county_name, :county, :cha_name, keyword_init: true
)

def catchment_for(unit_index, content, seed, cache)
  cache[unit_index] ||= begin
    facility_index = facility_index_for(unit_index)
    ward_index = ward_index_for(facility_index)
    sub_county_index = sub_county_index_for(ward_index)
    county = content.counties[sub_county_index % content.counties.length]
    cha_draw = Draw.new(seed, unit_index, "cha")
    cha_gender = cha_draw.chance?(0.6) ? "female" : "male"
    Catchment.new(
      unit_index: unit_index,
      unit_id: unit_location_id(unit_index),
      unit_name: format("Community Health Unit %d", unit_index + 1),
      facility_id: facility_location_id(facility_index),
      facility_name: format("%s Health Centre %d", county_short_name(county), facility_index + 1),
      ward_id: ward_location_id(ward_index),
      ward_name: format("Ward %d", ward_index + 1),
      sub_county_id: sub_county_location_id(sub_county_index),
      sub_county_name: format("%s Sub-County %d", county_short_name(county), sub_county_index + 1),
      county: county,
      cha_name: "#{given_names(cha_draw, cha_gender).first} #{cha_draw.pick(FAMILY_NAMES)}"
    )
  end
end

def location_resource(id:, name:, level:, level_display:, physical_code:, physical_display:, parent_id:, parent_name:)
  {
    "resourceType" => "Location",
    "id" => id,
    "identifier" => [{ "system" => LOCATION_IDENTIFIER_SYSTEM, "value" => id }],
    "status" => "active",
    "name" => name,
    "mode" => "instance",
    "type" => [{ "coding" => [{ "system" => ADMINISTRATIVE_LEVEL_SYSTEM, "code" => level, "display" => level_display }] }],
    "physicalType" => { "coding" => [{ "system" => PHYSICAL_TYPE_SYSTEM, "code" => physical_code, "display" => physical_display }] },
    "partOf" => reference("Location", parent_id, parent_name)
  }
end

def catchment_resources(catchment)
  county = catchment.county
  unit_tag = sync_tag(catchment.unit_id)
  [
    location_resource(id: catchment.sub_county_id, name: catchment.sub_county_name, level: "sub-county", level_display: "Sub-county",
                      physical_code: "jdn", physical_display: "Jurisdiction", parent_id: county["id"], parent_name: county["name"]),
    location_resource(id: catchment.ward_id, name: catchment.ward_name, level: "ward", level_display: "Ward",
                      physical_code: "jdn", physical_display: "Jurisdiction", parent_id: catchment.sub_county_id, parent_name: catchment.sub_county_name),
    location_resource(id: catchment.facility_id, name: catchment.facility_name, level: "facility", level_display: "Facility",
                      physical_code: "bu", physical_display: "Building", parent_id: catchment.ward_id, parent_name: catchment.ward_name),
    location_resource(id: catchment.unit_id, name: catchment.unit_name, level: "unit", level_display: "Community Health Unit",
                      physical_code: "area", physical_display: "Area", parent_id: catchment.facility_id, parent_name: catchment.facility_name),
    staff_practitioner(cha_practitioner_id(catchment.unit_index), catchment.cha_name, "CHA", catchment, Draw.new(0, catchment.unit_index, "cha-phone")),
    staff_role(cha_practitioner_role_id(catchment.unit_index), cha_practitioner_id(catchment.unit_index), catchment.cha_name, "CHA", catchment,
               REFERENCE_DATE - (400 + (catchment.unit_index % 900))).merge("meta" => unit_tag)
  ]
end

def staff_practitioner(id, name, role_group, catchment, draw)
  given, family = name.split(" ", 2)
  {
    "resourceType" => "Practitioner",
    "id" => id,
    "extension" => [
      { "url" => PRACTITIONER_LOCATION_EXTENSION, "valueReference" => reference("Location", catchment.unit_id, catchment.unit_name) },
      { "url" => PRACTITIONER_ROLE_GROUP_EXTENSION, "valueString" => role_group }
    ],
    "identifier" => [{ "system" => PRACTITIONER_IDENTIFIER_SYSTEM, "value" => id }],
    "active" => true,
    "name" => [{ "use" => "official", "family" => family, "given" => [given] }],
    "telecom" => [{ "system" => "phone", "value" => phone_number(draw), "use" => "mobile" }]
  }
end

def staff_role(id, practitioner_id, name, role_code, catchment, start_date)
  {
    "resourceType" => "PractitionerRole",
    "id" => id,
    "active" => true,
    "period" => { "start" => start_date.iso8601 },
    "practitioner" => reference("Practitioner", practitioner_id, name),
    "code" => [{ "coding" => [role_coding(role_code)] }],
    "location" => [reference("Location", catchment.unit_id, catchment.unit_name)]
  }
end

def chv_name(chw_index, seed)
  draw = Draw.new(seed, chw_index, "chv")
  gender = draw.chance?(0.7) ? "female" : "male"
  "#{given_names(draw, gender).first} #{draw.pick(FAMILY_NAMES)}"
end

def chw_resources(chw_index, catchment, seed)
  name = chv_name(chw_index, seed)
  role_id = chw_practitioner_role_id(chw_index)
  [
    staff_practitioner(practitioner_id(chw_index), name, "CHV", catchment, Draw.new(seed, chw_index, "chv-phone")),
    staff_role(role_id, practitioner_id(chw_index), name, "CHV", catchment, REFERENCE_DATE - (300 + (chw_index % 1200)))
      .merge("meta" => sync_tag(catchment.unit_id)),
    {
      "resourceType" => "CareTeam",
      "id" => care_team_id(chw_index),
      "meta" => sync_tag(catchment.unit_id),
      "status" => "active",
      "name" => "#{name} Care Team",
      "participant" => [
        { "role" => [{ "coding" => [role_coding("CHV")] }], "member" => reference("PractitionerRole", role_id, name) },
        { "role" => [{ "coding" => [role_coding("CHA")] }], "member" => reference("PractitionerRole", cha_practitioner_role_id(catchment.unit_index), catchment.cha_name) }
      ],
      "managingOrganization" => [reference("Organization", organization_id)]
    }
  ]
end

def organization_resource
  {
    "resourceType" => "Organization",
    "id" => organization_id,
    "active" => true,
    "name" => "eCHIS Benchmark Implementing Organization",
    "type" => [{
      "coding" => [{ "system" => "http://terminology.hl7.org/CodeSystem/organization-type", "code" => "prov", "display" => "Healthcare Provider" }]
    }]
  }
end

# --- Household roster ------------------------------------------------------------

Person = Struct.new(:index, :id, :role, :relationship, :gender, :age_days, :given, :family, :phone, keyword_init: true) do
  def birth_date = REFERENCE_DATE - age_days
  def age_years = age_days / 365
  def age_months = age_days / 30
end

RELATIONSHIP_DISPLAYS = { "SPS" => "Spouse", "CHILD" => "Child", "PRN" => "Parent" }.freeze
INVERSE_RELATIONSHIP = { "SPS" => "SPS", "CHILD" => "PRN", "PRN" => "CHILD" }.freeze
UNDER_FIVE_SHARE_OF_CHILDREN = 0.45

def household_roster(household_index, individuals_per_household, seed)
  draw = Draw.new(seed, household_index, "household")
  family = draw.pick(FAMILY_NAMES)
  head_gender = draw.chance?(0.35) ? "female" : "male"
  head_age = draw.int(22, 70)
  size = household_size(household_index, individuals_per_household)
  start = first_individual_index(household_index, individuals_per_household)

  Array.new(size) do |offset|
    index = start + offset
    person_draw = Draw.new(seed, index, "person")
    role, relationship, gender, age_days =
      if offset.zero?
        ["head", nil, head_gender, (head_age * 365) + person_draw.int(0, 364)]
      elsif offset == 1 && person_draw.chance?(0.8)
        spouse_age = (head_age + person_draw.int(-8, 3)).clamp(18, 80)
        ["spouse", "SPS", head_gender == "female" ? "male" : "female", (spouse_age * 365) + person_draw.int(0, 364)]
      elsif offset == size - 1 && size >= 4 && person_draw.chance?(0.12)
        ["parent", "PRN", person_draw.chance?(0.6) ? "female" : "male", (person_draw.int(60, 88) * 365) + person_draw.int(0, 364)]
      else
        max_child_days = [((head_age - 15) * 365) - 1, 0].max
        child_days =
          if person_draw.chance?(UNDER_FIVE_SHARE_OF_CHILDREN)
            person_draw.int(0, (5 * 365) - 1)
          else
            person_draw.int(5 * 365, (18 * 365) - 1)
          end
        ["child", "CHILD", person_draw.chance?(0.5) ? "female" : "male", [child_days, max_child_days].min]
      end
    Person.new(
      index: index, id: patient_id(index), role: role, relationship: relationship, gender: gender, age_days: age_days,
      given: given_names(person_draw, gender), family: family, phone: age_days >= 18 * 365 ? phone_number(person_draw) : nil
    )
  end
end

def patient_resource(person, head, catchment, household_index, chv, deceased_at)
  resource = {
    "resourceType" => "Patient",
    "id" => person.id,
    "meta" => sync_tag(catchment.unit_id),
    "identifier" => [{ "system" => PATIENT_IDENTIFIER_SYSTEM, "value" => person.id }],
    "active" => true,
    "name" => [{ "use" => "official", "family" => person.family, "given" => person.given }]
  }
  resource["telecom"] = [{ "system" => "phone", "value" => person.phone, "use" => "mobile" }] if person.phone
  resource["gender"] = person.gender
  resource["birthDate"] = person.birth_date.iso8601
  resource["deceasedDateTime"] = timestamp(deceased_at) if deceased_at
  resource["address"] = [household_address(catchment, household_index)]
  if person.relationship
    resource["contact"] = [{
      "relationship" => [{ "coding" => [{ "system" => ROLE_CODE_SYSTEM, "code" => person.relationship, "display" => RELATIONSHIP_DISPLAYS[person.relationship] }] }],
      "name" => { "family" => head.family, "given" => head.given }
    }]
  end
  resource["generalPractitioner"] = [reference("PractitionerRole", chv[:role_id], chv[:name])]
  resource
end

def village_name(household_index) = format("Village %d", (household_index / 250) + 1)

def household_address(catchment, household_index)
  {
    "use" => "home",
    "line" => ["#{village_name(household_index)}, #{catchment.ward_name}"],
    "city" => village_name(household_index),
    "district" => catchment.sub_county_name,
    "state" => county_short_name(catchment.county),
    "country" => "KE"
  }
end

def related_person_resource(person, head, catchment)
  code = INVERSE_RELATIONSHIP.fetch(person.relationship)
  resource = {
    "resourceType" => "RelatedPerson",
    "id" => related_person_id(person.index),
    "meta" => sync_tag(catchment.unit_id),
    "active" => true,
    "patient" => reference("Patient", person.id),
    "relationship" => [{ "coding" => [{ "system" => ROLE_CODE_SYSTEM, "code" => code, "display" => RELATIONSHIP_DISPLAYS[code] }] }],
    "name" => [{ "use" => "official", "family" => head.family, "given" => head.given }],
    "gender" => head.gender
  }
  resource["telecom"] = [{ "system" => "phone", "value" => head.phone, "use" => "mobile" }] if head.phone
  resource
end

def group_resource(household_index, roster, catchment, chv, registered_on)
  head = roster.first
  {
    "resourceType" => "Group",
    "id" => household_id(household_index),
    "meta" => sync_tag(catchment.unit_id),
    "identifier" => [{ "system" => HOUSEHOLD_IDENTIFIER_SYSTEM, "value" => household_id(household_index) }],
    "active" => true,
    "type" => "person",
    "actual" => true,
    "name" => "#{head.family} Household",
    "managingEntity" => reference("PractitionerRole", chv[:role_id], chv[:name]),
    "member" => roster.map do |person|
      { "entity" => reference("Patient", person.id, full_name(person)), "period" => { "start" => registered_on.iso8601 } }
    end
  }
end

