# A fact pins an answer instead of drawing it: a literal FHIR answer hash
# ({"valueString" => ...}), or OptionCode to select the item's own
# answerOption with that code (so system/display come from the form).
OptionCode = Struct.new(:code)

ResponseState = Struct.new(:draw, :answers, :extracted, :display_name, :visit_date, keyword_init: true)

def observation_extract?(item)
  Array(item["extension"]).any? { |extension| extension["url"] == OBSERVATION_EXTRACT_EXTENSION && extension["valueBoolean"] == true }
end

def answer_scalar(answer)
  key = answer.keys.find { |k| k.start_with?("value") }
  value = answer[key]
  value.is_a?(Hash) ? value["code"] : value
end

def enable_when_met?(condition, answers)
  answer = answers[condition["question"]]
  operator = condition["operator"]
  return answer.nil? != condition["answerBoolean"] if operator == "exists"
  return operator == "!=" if answer.nil?

  expected_key = condition.keys.find { |key| key.start_with?("answer") }
  expected = condition[expected_key]
  expected = expected["code"] if expected.is_a?(Hash)
  actual = answer_scalar(answer)

  case operator
  when "=" then actual == expected
  when "!=" then actual != expected
  when ">", "<", ">=", "<="
    actual.is_a?(Numeric) && expected.is_a?(Numeric) ? actual.public_send(operator, expected) : false
  else false
  end
end

def item_enabled?(item, answers)
  conditions = Array(item["enableWhen"])
  return true if conditions.empty?

  results = conditions.map { |condition| enable_when_met?(condition, answers) }
  item["enableBehavior"] == "any" ? results.any? : results.all?
end

def render_text(text, state) = text.gsub("{{name}}", state.display_name)

def choose_option(options, profile, draw)
  if profile && profile[:weights]
    pairs = options.filter_map { |option| weight = profile[:weights][option["code"]]; [option, weight] if weight&.positive? }
    return draw.weighted(pairs) unless pairs.empty?
  end

  codes = options.map { |option| option["code"] }
  if codes.sort == %w[no yes]
    yes = draw.chance?(profile&.fetch(:p_yes, nil) || DEFAULT_P_YES)
    return options.find { |option| option["code"] == (yes ? "yes" : "no") }
  end

  none = options.find { |option| option["code"] == "none" }
  return none if none && draw.chance?(NONE_OPTION_PROBABILITY)

  others = options.reject { |option| option.equal?(none) }
  draw.pick(others.empty? ? options : others)
end

def drawn_answer(item, state)
  profile = ANSWER_PROFILES[item["linkId"]]
  draw = state.draw
  return nil if profile&.key?(:p_answer) && !draw.chance?(profile[:p_answer])

  case item["type"]
  when "choice", "open-choice"
    options = Array(item["answerOption"]).filter_map { |option| option["valueCoding"] }
    return nil if options.empty?

    { "valueCoding" => choose_option(options, profile, draw) }
  when "boolean"
    { "valueBoolean" => draw.chance?(profile&.fetch(:p_true, nil) || 0.5) }
  when "integer"
    range = profile&.fetch(:range, nil) || (0..10)
    { "valueInteger" => draw.int(range.min, range.max) }
  when "decimal"
    range = profile&.fetch(:range, nil) || (0.0..10.0)
    { "valueDecimal" => (range.min + (draw.float * (range.max - range.min))).round(1) }
  when "date"
    offset = item["linkId"].match?(/next|appointment|edd|follow-up/) ? draw.int(7, 60) : -draw.int(0, 60)
    { "valueDate" => (state.visit_date + offset).iso8601 }
  when "string", "text"
    item["required"] ? { "valueString" => "Recorded during CHP home visit" } : nil
  end
end

def resolve_answer(item, state, facts)
  link_id = item["linkId"]
  return drawn_answer(item, state) unless facts.key?(link_id)

  fact = facts[link_id]
  return fact unless fact.is_a?(OptionCode)

  option = Array(item["answerOption"]).filter_map { |o| o["valueCoding"] }.find { |coding| coding["code"] == fact.code }
  option ? { "valueCoding" => option } : nil
end

def response_items(items, state, facts)
  Array(items).flat_map do |item|
    next [] unless item_enabled?(item, state.answers)

    node = { "linkId" => item["linkId"] }
    node["text"] = render_text(item["text"], state) if item["text"]

    case item["type"]
    when "group"
      repeats = facts[item["linkId"]]
      fact_sets = repeats.is_a?(Array) ? repeats : [{}]
      fact_sets.filter_map do |fact_set|
        children = response_items(item["item"], state, facts.merge(fact_set))
        children.empty? ? nil : node.merge("item" => children)
      end
    when "display"
      [node]
    else
      answer = resolve_answer(item, state, facts)
      if answer
        state.answers[item["linkId"]] = answer
        state.extracted << [item, answer] if observation_extract?(item)
        nested = response_items(item["item"], state, facts)
        node["answer"] = [nested.empty? ? answer : answer.merge("item" => nested)]
      end
      [node]
    end
  end
end

# --- Visits ---------------------------------------------------------------------

Visit = Struct.new(:slug, :questionnaire, :plan_definition_id, :person, :start_time, :end_time, :encounter_id,
                   :response_id, :answers, :observations, :resources, keyword_init: true) do
  # Extracted Observations by their code, each as [observation, scalar value, item].
  def observation_for(code) = observations.find { |entry| entry.first.dig("code", "coding", 0, "code") == code }
  def value_for(code) = observation_for(code)&.at(1)
  def date = start_time.to_date
end

GenerationContext = Struct.new(:content, :seed, :catchment, :chv, :include_specimen, keyword_init: true)

def observation_value(item, answer)
  if answer["valueCoding"]
    { "valueCodeableConcept" => { "coding" => [answer["valueCoding"]] } }
  elsif answer.key?("valueDecimal")
    quantity = { "value" => answer["valueDecimal"] }
    quantity.merge!("unit" => "Cel", "system" => "http://unitsofmeasure.org", "code" => "Cel") if item.dig("code", 0, "code") == "temperature-celsius"
    { "valueQuantity" => quantity }
  elsif answer.key?("valueDate")
    { "valueDateTime" => answer["valueDate"] }
  else
    key = answer.keys.find { |k| k.start_with?("value") }
    { key => answer[key] }
  end
end

# Walks one form for one person and returns the Encounter, the
# QuestionnaireResponse and its extracted Observations -- the same trio the
# app writes for every service visit. subject/encounter wiring mirrors the
# dev server: household forms target the Group and have no Encounter.
def run_visit(ctx, slug:, questionnaire_id:, plan_definition_id:, person:, subject:, facts: {}, day_window: 0..89, with_encounter: true)
  questionnaire = ctx.content.questionnaire(questionnaire_id)
  draw = Draw.new(ctx.seed, person.index, slug)
  date = REFERENCE_DATE - draw.int(day_window.min, day_window.max)
  start_time = day_time(date, draw.int(0, 600))
  end_time = start_time + (draw.int(3, 25) * 60)
  state = ResponseState.new(draw: draw, answers: {}, extracted: [], display_name: person.given.first, visit_date: date)
  items = response_items(questionnaire["item"], state, facts)

  encounter_id = with_encounter ? visit_resource_id("enc", slug, person.index) : nil
  response_id = visit_resource_id("qr", slug, person.index)
  tag = sync_tag(ctx.catchment.unit_id)
  resources = []

  if with_encounter
    resources << {
      "resourceType" => "Encounter",
      "id" => encounter_id,
      "meta" => tag,
      "extension" => [plan_definition_extension(plan_definition_id)],
      "status" => "finished",
      "class" => { "system" => ACT_CODE_SYSTEM, "code" => "FLD", "display" => "Field" },
      "subject" => subject,
      "period" => { "start" => timestamp(start_time), "end" => timestamp(end_time) }
    }
  end

  response = {
    "resourceType" => "QuestionnaireResponse",
    "id" => response_id,
    "meta" => tag,
    "extension" => [
      { "url" => LAST_LAUNCHED_EXTENSION, "valueDateTime" => timestamp(start_time) },
      plan_definition_extension(plan_definition_id)
    ],
    "questionnaire" => questionnaire["url"],
    "status" => "completed",
    "subject" => subject
  }
  response["encounter"] = reference("Encounter", encounter_id) if encounter_id
  response["authored"] = timestamp(end_time)
  response["item"] = items
  resources << response

  observations = state.extracted.each_with_index.map do |(item, answer), position|
    observation = {
      "resourceType" => "Observation",
      "id" => visit_resource_id("obs", slug, person.index, position),
      "meta" => tag,
      "status" => "final",
      "code" => { "coding" => [item.dig("code", 0).slice("system", "code", "display")] },
      "subject" => subject
    }
    observation["encounter"] = reference("Encounter", encounter_id) if encounter_id
    observation["effectiveDateTime"] = timestamp(end_time)
    observation.merge!(observation_value(item, answer))
    observation["derivedFrom"] = [reference("QuestionnaireResponse", response_id)]
    resources << observation
    [observation, answer_scalar(answer), item]
  end

  Visit.new(slug: slug, questionnaire: questionnaire, plan_definition_id: plan_definition_id, person: person,
            start_time: start_time, end_time: end_time, encounter_id: encounter_id, response_id: response_id,
            answers: state.answers, observations: observations, resources: resources)
end

def detected_issue(ctx, visit, rule_id, evidence, position)
  observation, value, item = evidence
  display_value = observation.dig("valueCodeableConcept", "coding", 0, "display") || value.to_s
  question = item["text"].to_s.gsub("{{name}}", visit.person.given.first)
  {
    "resourceType" => "DetectedIssue",
    "id" => visit_resource_id("di", visit.slug, visit.person.index, position),
    "meta" => sync_tag(ctx.catchment.unit_id),
    "extension" => [plan_definition_extension(rule_id)],
    "status" => "preliminary",
    "code" => { "coding" => [{ "system" => DECISION_SUPPORT_RULE_SYSTEM, "code" => rule_id, "display" => ctx.content.plan_title(rule_id) }] },
    "severity" => "high",
    "patient" => reference("Patient", visit.person.id),
    "identifiedDateTime" => timestamp(visit.end_time),
    "author" => reference("PractitionerRole", ctx.chv[:role_id]),
    "implicated" => [reference("QuestionnaireResponse", visit.response_id)],
    "evidence" => [{ "detail" => [reference("Observation", observation["id"])] }],
    "detail" => "#{question} of #{display_value} recorded on #{visit.date.strftime("%d-%m-%Y")} while completing #{visit.questionnaire["title"]}."
  }
end

def follow_up_task(ctx, visit, slug:, plan_definition_id:, activity:, code:, display:, priority:, status:, due_in_days:, reason: nil)
  task = {
    "resourceType" => "Task",
    "id" => visit_resource_id("task", slug, visit.person.index),
    "meta" => sync_tag(ctx.catchment.unit_id),
    "extension" => [plan_definition_extension(plan_definition_id)],
    "instantiatesCanonical" => "ActivityDefinition/#{activity}",
    "status" => status,
    "intent" => "order",
    "priority" => priority,
    "code" => { "coding" => [{ "code" => code, "display" => display }] },
    "for" => reference("Patient", visit.person.id),
    "authoredOn" => timestamp(visit.end_time),
    "owner" => reference("PractitionerRole", ctx.chv[:role_id], ctx.chv[:name]),
    "restriction" => { "period" => { "end" => (visit.date + due_in_days).iso8601 } }
  }
  task["reasonReference"] = reference("DetectedIssue", reason["id"]) if reason
  task
end

