def condition_resource(ctx, visit, key, verification)
  {
    "resourceType" => "Condition",
    "id" => visit_resource_id("cond", visit.slug, visit.person.index),
    "meta" => sync_tag(ctx.catchment.unit_id),
    "clinicalStatus" => { "coding" => [{ "system" => "http://terminology.hl7.org/CodeSystem/condition-clinical", "code" => "active" }] },
    "verificationStatus" => { "coding" => [{ "system" => "http://terminology.hl7.org/CodeSystem/condition-ver-status", "code" => verification }] },
    "category" => [{ "coding" => [{ "system" => "http://terminology.hl7.org/CodeSystem/condition-category", "code" => "problem-list-item" }] }],
    "code" => { "coding" => [{ "system" => SNOMED_SYSTEM }.merge(CONDITION_CODES.fetch(key))] },
    "subject" => reference("Patient", visit.person.id),
    "encounter" => reference("Encounter", visit.encounter_id),
    "recordedDate" => timestamp(visit.end_time),
    "recorder" => reference("PractitionerRole", ctx.chv[:role_id]),
    "evidence" => [{ "detail" => [reference("QuestionnaireResponse", visit.response_id)] }]
  }
end

def yes?(value) = value == "yes"

def fast_breathing_threshold(person)
  return 60 if person.age_months < 2
  return 50 if person.age_months < 12

  40
end

# Decision rules, keyed to the snapshot's decision-support PlanDefinitions
# (their ids double as the DetectedIssue code, as on the dev server).
UNDER_FIVE_ALERT_RULES = [
  ["under-5-fast-breathing-alert", "breaths-per-minute", ->(value, person, _) { value >= fast_breathing_threshold(person) }],
  ["under-5-high-temperature-alert", "temperature-celsius", ->(value, _, _) { value >= 38.0 }],
  ["under-5-low-temperature-alert", "temperature-celsius", ->(value, _, _) { value <= 35.4 }],
  ["under-5-diarrhoea-over-14-days-alert", "diarrhoea-duration-days", ->(value, _, _) { value > 14 }],
  ["under-5-blood-in-stool-alert", "blood-in-stool", ->(value, _, _) { yes?(value) }],
  ["under-5-chest-in-drawing-alert", "chest-in-drawing", ->(value, _, _) { yes?(value) }],
  ["under-5-convulsions-alert", "convulsions", ->(value, _, _) { yes?(value) }],
  ["under-5-unable-to-drink-or-feed-alert", "unable-to-drink-or-feed", ->(value, _, _) { yes?(value) }],
  ["under-5-vomiting-everything-alert", "vomiting-everything", ->(value, _, _) { yes?(value) }],
  ["under-5-unusually-sleepy-or-unconscious-alert", "unusually-sleepy-or-unconscious", ->(value, _, _) { yes?(value) }],
  ["under-5-muac-red-alert", "muac-color", ->(value, _, _) { value == "red" }],
  ["under-5-muac-yellow-alert", "muac-color", ->(value, _, _) { value == "yellow" }],
  ["under-5-swelling-of-both-feet-alert", "swelling-of-both-feet", ->(value, _, _) { yes?(value) }],
  ["under-5-malaria-negative-with-fever-alert", "malaria-rdt-result", ->(value, _, visit) { value == "negative" && yes?(visit.value_for("fever")) }]
].freeze
CORE_DANGER_SIGN_CODES = %w[chest-in-drawing convulsions unable-to-drink-or-feed vomiting-everything unusually-sleepy-or-unconscious].freeze
ANY_CORE_DANGER_SIGN_RULE = "under-5-any-core-danger-sign-refer-immediately-alert"

def alerts_for(ctx, visit, rules)
  issues = []
  rules.each do |rule_id, code, predicate|
    evidence = visit.observation_for(code)
    next unless evidence && predicate.call(evidence[1], visit.person, visit)

    issues << detected_issue(ctx, visit, rule_id, evidence, issues.length)
  end
  issues
end

# A referral raised during a visit becomes an urgent Task for the CHV; about
# half are already closed out by a Referral Follow Up visit.
def referral_resources(ctx, visit, issues)
  return [] if issues.empty?

  draw = Draw.new(ctx.seed, visit.person.index, "#{visit.slug}-referral")
  followed_up = draw.chance?(0.5)
  resources = [
    follow_up_task(ctx, visit, slug: "ref#{visit.slug}", plan_definition_id: "plandefinition-referral-follow-up-alert",
                   activity: "act-refer-patient", code: "follow-up-on-referral", display: "Follow up on referral",
                   priority: "urgent", status: followed_up ? "completed" : "requested", due_in_days: 3, reason: issues.first)
  ]
  if followed_up
    resources.concat(run_visit(ctx, slug: "fu#{visit.slug}", questionnaire_id: "referral-follow-up-questionnaire",
                               plan_definition_id: "plandefinition-referral-follow-up", person: visit.person,
                               subject: reference("Patient", visit.person.id), day_window: 0..0).resources)
  end
  resources
end

def under_five_visit(ctx, person)
  breaths_draw = Draw.new(ctx.seed, person.index, "u5-breaths")
  threshold = fast_breathing_threshold(person)
  facts = { "how-many-breaths-per-minute" => { "valueInteger" => breaths_draw.int(threshold - 18, threshold + 2) } }
  visit = run_visit(ctx, slug: "u5", questionnaire_id: "under-5-assessment-service-questionnaire",
                    plan_definition_id: "plandefinition-under-5-workflow", person: person,
                    subject: reference("Patient", person.id), facts: facts)
  resources = visit.resources.dup
  issues = alerts_for(ctx, visit, UNDER_FIVE_ALERT_RULES)
  core = CORE_DANGER_SIGN_CODES.filter_map { |code| visit.observation_for(code) if yes?(visit.value_for(code)) }.first
  issues << detected_issue(ctx, visit, ANY_CORE_DANGER_SIGN_RULE, core, issues.length) if core
  resources.concat(issues)

  if visit.value_for("malaria-rdt-result") == "positive"
    resources << condition_resource(ctx, visit, "malaria", "provisional")
  end
  if ctx.include_specimen && visit.observation_for("malaria-rdt-result")
    resources << {
      "resourceType" => "Specimen",
      "id" => format("echis-spec%08d", person.index),
      "meta" => sync_tag(ctx.catchment.unit_id),
      "status" => "available",
      "type" => { "coding" => [{ "system" => SNOMED_SYSTEM, "code" => "119297000", "display" => "Blood specimen" }] },
      "subject" => reference("Patient", person.id),
      "collection" => { "collectedDateTime" => timestamp(visit.end_time) }
    }
  end
  resources.concat(referral_resources(ctx, visit, issues))
end

IMMUNIZATION_ALERT_RULES = [
  ["immunization-delayed-developmental-milestone-refer-alert", "delayed-milestone", ->(_, _, _) { true }],
  ["immunization-defaulter-other-reasons-refer-alert", "not-up-to-date-reason", ->(value, _, _) { value == "defaulter-other" }]
].freeze

def immunization_visit(ctx, person)
  visit = run_visit(ctx, slug: "imm", questionnaire_id: "immunization-service-questionnaire",
                    plan_definition_id: "plandefinition-immunization-service", person: person,
                    subject: reference("Patient", person.id))
  resources = visit.resources.dup
  issues = alerts_for(ctx, visit, IMMUNIZATION_ALERT_RULES)
  resources.concat(issues)
  resources.concat(referral_resources(ctx, visit, issues))

  if visit.observation_for("not-up-to-date-reason") && Draw.new(ctx.seed, person.index, "defaulter").chance?(0.5)
    tracing = run_visit(ctx, slug: "dft", questionnaire_id: "defaulter-follow-up-questionnaire",
                        plan_definition_id: "plandefinition-defaulter-follow-up", person: person,
                        subject: reference("Patient", person.id), day_window: 0..0)
    resources.concat(tracing.resources)
  end
  resources
end

def pregnancy_visits(ctx, person)
  screening = run_visit(ctx, slug: "psr", questionnaire_id: "pregnancy-screening-registration-questionnaire",
                        plan_definition_id: "plandefinition-pregnancy-screening-registration", person: person,
                        subject: reference("Patient", person.id), day_window: 60..200)
  resources = screening.resources.dup
  resources << condition_resource(ctx, screening, "pregnancy", "confirmed")

  draw = Draw.new(ctx.seed, person.index, "anc")
  if draw.chance?(0.7)
    home = run_visit(ctx, slug: "anc", questionnaire_id: "pregnancy-home-service-questionnaire",
                     plan_definition_id: "plandefinition-pregnancy-home-service", person: person,
                     subject: reference("Patient", person.id), day_window: 0..59)
    resources.concat(home.resources)
  end
  resources << follow_up_task(ctx, screening, slug: "anc", plan_definition_id: "plandefinition-pregnancy-home-service",
                              activity: "act-general-assessment", code: "pregnancy-home-service", display: "Pregnancy Home Service",
                              priority: "routine", status: "requested", due_in_days: 30)
end

def postnatal_visit(ctx, mother)
  visit = run_visit(ctx, slug: "pnc", questionnaire_id: "mother-newborn-pnc-home-service-questionnaire",
                    plan_definition_id: "plandefinition-mother-newborn-pnc-home-service", person: mother,
                    subject: reference("Patient", mother.id), day_window: 0..30)
  issues = alerts_for(ctx, visit, [["plandefinition-pnc-mother-danger-sign-alert", "pnc-mother-danger-sign", ->(_, _, _) { true }]])
  visit.resources + issues + referral_resources(ctx, visit, issues)
end

def chronic_visit(ctx, person, slug, questionnaire_id, plan_definition_id, condition_key)
  visit = run_visit(ctx, slug: slug, questionnaire_id: questionnaire_id, plan_definition_id: plan_definition_id,
                    person: person, subject: reference("Patient", person.id))
  visit.resources + [condition_resource(ctx, visit, condition_key, "confirmed")]
end

# Visit mix per individual. Under-5 care dominates (every under-5 child has
# an assessment; most also an immunization visit), pregnancy and postnatal
# care are next, and chronic care and death reports are rare -- the mix
# agreed for the dev-server-aligned dataset. Returns [resources, deceased_at].
PREGNANCY_RATE = 0.08
POSTNATAL_RATE = 0.6
DIABETES_RATE = 0.05
TB_RATE = 0.006
DEATH_RATE = 0.015

def person_visits(ctx, person, roster)
  draw = Draw.new(ctx.seed, person.index, "visit-mix")
  resources = []
  deceased_at = nil
  under_five = person.age_months < 60

  if under_five
    resources.concat(under_five_visit(ctx, person))
    resources.concat(immunization_visit(ctx, person)) if draw.chance?(person.age_months < 24 ? 0.7 : 0.3)
  end

  woman_of_reproductive_age = person.gender == "female" && person.age_years.between?(15, 49) && %w[head spouse].include?(person.role)
  if woman_of_reproductive_age
    resources.concat(pregnancy_visits(ctx, person)) if draw.chance?(PREGNANCY_RATE)
    has_infant = roster.any? { |member| member.role == "child" && member.age_days < 180 }
    resources.concat(postnatal_visit(ctx, person)) if has_infant && draw.chance?(POSTNATAL_RATE)
  end

  if person.age_years >= 35 && draw.chance?(DIABETES_RATE)
    resources.concat(chronic_visit(ctx, person, "dm", "diabetes-service-questionnaire", "plandefinition-diabetes-service", "diabetes"))
  end
  if person.age_years >= 15 && draw.chance?(TB_RATE)
    resources.concat(chronic_visit(ctx, person, "tb", "tb-service-questionnaire", "plandefinition-tb-service", "tb"))
  end
  if person.age_years >= 60 && draw.chance?(DEATH_RATE)
    report = run_visit(ctx, slug: "death", questionnaire_id: "death-report-questionnaire",
                       plan_definition_id: "plandefinition-death-report", person: person,
                       subject: reference("Patient", person.id), day_window: 0..0)
    resources.concat(report.resources)
    deceased_at = report.start_time - (2 * 86_400)
  end

  [resources, deceased_at]
end

WASH_OBSERVATIONS = [
  ["water-source", "Main drinking water source"],
  ["sanitation-facility", "Household sanitation facility"],
  ["handwashing-facility", "Handwashing facility available"]
].freeze

def household_registration(ctx, household_index, roster, group_reference)
  head = roster.first
  catchment = ctx.catchment
  national_id_draw = Draw.new(ctx.seed, head.index, "national-id")
  facts = {
    "household-id" => { "valueString" => household_id(household_index) },
    "household-name" => { "valueString" => "#{head.family} Household" },
    "county" => { "valueString" => catchment.county["name"] },
    "sub-county" => { "valueString" => catchment.sub_county_name },
    "ward" => { "valueString" => catchment.ward_name },
    "village" => { "valueString" => village_name(household_index) },
    "head-given-name" => { "valueString" => head.given.join(" ") },
    "head-family-name" => { "valueString" => head.family },
    "head-national-id" => { "valueString" => format("%08d", national_id_draw.int(10_000_000, 39_999_999)) },
    "head-gender" => OptionCode.new(head.gender),
    "head-birth-date" => { "valueDate" => head.birth_date.iso8601 },
    "head-phone" => head.phone ? { "valueString" => head.phone } : nil,
    "household-members" => roster.drop(1).map do |member|
      {
        "member-given-name" => { "valueString" => member.given.join(" ") },
        "member-family-name" => { "valueString" => member.family },
        "member-gender" => OptionCode.new(member.gender),
        "member-birth-date" => { "valueDate" => member.birth_date.iso8601 },
        "member-relationship-to-head" => OptionCode.new(member.relationship)
      }
    end
  }
  registration = run_visit(ctx, slug: "hh", questionnaire_id: "household-registration",
                           plan_definition_id: "plandefinition-household-registration", person: head,
                           subject: group_reference, facts: facts, day_window: 90..540, with_encounter: false)
  response = registration.resources.first
  response["extension"].pop # the dev server's household registrations carry no PlanDefinition link

  observations = WASH_OBSERVATIONS.each_with_index.filter_map do |(link_id, display), position|
    answer = registration.answers[link_id]
    next unless answer

    {
      "resourceType" => "Observation",
      "id" => format("echis-obs-hh%08d-%d", household_index, position),
      "meta" => sync_tag(catchment.unit_id),
      "status" => "final",
      "code" => { "coding" => [{ "system" => HOUSEHOLD_WASH_SYSTEM, "code" => link_id, "display" => display }] },
      "subject" => group_reference,
      "effectiveDateTime" => response["authored"]
    }.merge(observation_value({}, answer)).merge("derivedFrom" => [reference("QuestionnaireResponse", response["id"])])
  end

  [registration, [response] + observations]
end

def resources_for_household(household_index, individuals_per_household, content, seed, include_specimen, catchment_cache)
  chw_index = chw_index_for(household_index)
  catchment = catchment_for(unit_index_for(chw_index), content, seed, catchment_cache)
  chv = { role_id: chw_practitioner_role_id(chw_index), name: chv_name(chw_index, seed) }
  ctx = GenerationContext.new(content: content, seed: seed, catchment: catchment, chv: chv, include_specimen: include_specimen)
  roster = household_roster(household_index, individuals_per_household, seed)
  head = roster.first

  group_reference = reference("Group", household_id(household_index))
  registration, registration_resources = household_registration(ctx, household_index, roster, group_reference)
  registered_on = registration.date

  people = []
  visits = []
  roster.each do |person|
    person_resources, deceased_at = person_visits(ctx, person, roster)
    people << patient_resource(person, head, catchment, household_index, chv, deceased_at)
    people << related_person_resource(person, head, catchment) if person.relationship
    visits.concat(person_resources)
  end

  [group_resource(household_index, roster, catchment, chv, registered_on)] + people + registration_resources + visits
end

PROGRESS_BAR_WIDTH = 24

def progress_bar(percent)
  filled = ((PROGRESS_BAR_WIDTH * percent) / 100.0).round.clamp(0, PROGRESS_BAR_WIDTH)
  ("#" * filled) + ("." * (PROGRESS_BAR_WIDTH - filled))
end

# Renders a "count and percentage" progress update for the current batch.
# Throttled to at most one line per whole percentage point crossed (plus
# always on the final batch), so a run of thousands of batches doesn't
# flood the log regardless of --batch-size. On a real terminal, updates
# overwrite the same line via \r for a live-looking progress bar; anywhere
# else (piped to a file, captured by `scripts/lab`, streamed through the
# Lab Control UI's SSE log -- none of which interpret \r as "overwrite
# the previous line") each update is emitted as its own line instead.
def report_progress(verb, done, total, shard_index, shard_count, last_reported_percent)
  percent = total.positive? ? ((done * 100.0) / total) : 100.0
  floor_percent = percent.floor
  finished = done >= total
  return last_reported_percent unless finished || floor_percent > last_reported_percent

  line = format(
    "%s households %d/%d [%s] %3d%% (shard %d/%d)",
    verb, done, total, progress_bar(percent), floor_percent, shard_index, shard_count
  )

  if $stdout.tty?
    print "\r#{line}"
    print "\n" if finished
    $stdout.flush
  else
    puts line
  end

  floor_percent
end

def require_option(options, key)
  value = options[key]
  return value unless value.nil? || value.to_s.empty?

  raise SeedError, "missing required option --#{key.to_s.tr("_", "-")}"
end

begin
  households = require_option(options, :households)
  individuals_per_household = require_option(options, :individuals_per_household)
  seed = require_option(options, :seed)
  run_id = require_option(options, :run_id)
  metadata_path = require_option(options, :metadata)
  batch_size = require_option(options, :batch_size)
  timeout = require_option(options, :timeout)
  max_retries = require_option(options, :max_retries)
  shard_index = require_option(options, :shard_index)
  shard_count = require_option(options, :shard_count)
  metadata_only = options[:metadata_only]

  raise SeedError, "--households must be greater than zero" unless households.positive?
  raise SeedError, "--individuals-per-household must be greater than zero" unless individuals_per_household.positive?
  raise SeedError, "--seed must be non-negative" if seed.negative?
  raise SeedError, "--batch-size must be greater than zero" unless batch_size.positive?
  raise SeedError, "--timeout must be greater than zero" unless timeout.positive?
  raise SeedError, "--max-retries must be non-negative" if max_retries.negative?
  raise SeedError, "--shard-count must be greater than zero" unless shard_count.positive?
  raise SeedError, "--shard-index must be non-negative and less than --shard-count" unless shard_index >= 0 && shard_index < shard_count

  fhir_base_url = options[:fhir_base_url].to_s.sub(%r{/+\z}, "")
  uri = nil
  unless metadata_only
    raise SeedError, "missing required option --fhir-base-url" if fhir_base_url.empty?

    uri = URI(fhir_base_url)
    raise SeedError, "FHIR base URL must be http or https: #{fhir_base_url}" unless %w[http https].include?(uri.scheme)
  end

  content = load_content(options[:content])

  # Contiguous household index range for this shard, per
  # specs/008-echis-workload-benchmark/contracts/echis-seed-cli.md's sharding
  # contract. Resource IDs are derived only from global household/individual
  # indices, never from shard_index itself, so re-running a single shard
  # reproduces byte-identical output and shards never collide.
  start_index = (households * shard_index) / shard_count
  end_index = (households * (shard_index + 1)) / shard_count

  started_at = Time.now.utc
  http_status_counts = Hash.new(0)
  fhir_response_status_counts = Hash.new(0)
  errors = []
  imported_entry_count = 0
  transaction_bundle_count = 0
  resource_counts = Hash.new(0)
  catchment_cache = {}
  emitted_unit_indices = Set.new
  emitted_chw_indices = Set.new
  organization_emitted = false
  last_reported_percent = -1

  # Counts one submitted bundle's response into the metadata tallies.
  # Returns true when the bundle was accepted in full.
  record_response = lambda do |response, entries, batch, count_imports|
    http_status_counts[response.code] += 1
    unless response.code.to_i >= 200 && response.code.to_i < 300
      errors << { "batch" => batch, "http_status" => response.code, "message" => response.body.to_s[0, 500] }
      next false
    end

    entries_response = response_entries(response.body)
    if entries_response.length < entries.length
      errors << {
        "batch" => batch,
        "http_status" => response.code,
        "message" => "partial transaction response: expected at least #{entries.length} entries, got #{entries_response.length}"
      }
    end
    entries_response.each do |entry|
      status = entry.dig("response", "status").to_s
      fhir_response_status_counts[status] += 1 if count_imports
      imported_entry_count += 1 if count_imports && status_success?(status)
    end
    entries_response.length >= entries.length
  end

  # Reference content goes in first, from every shard: household data
  # references the county Locations, and shards start in parallel. It is
  # counted (and reported as imported) by shard 0 only, so a merged
  # multi-shard metadata file counts it once.
  count_content = shard_index.zero?
  content.resources.each { |resource| resource_counts[resource["resourceType"]] += 1 } if count_content
  content_entries = content.resources.map { |resource| put_entry(resource) }
  if metadata_only
    imported_entry_count += content_entries.length if count_content
  else
    begin
      response = post_bundle_with_retries(uri, { "resourceType" => "Bundle", "type" => "transaction", "entry" => content_entries }, timeout, max_retries)
      unless record_response.call(response, content_entries, "content", count_content)
        raise SeedError, "reference content load failed (HTTP #{response.code}), and household data depends on it: #{errors.last&.fetch("message", nil)}"
      end
    rescue SeedError
      raise
    rescue StandardError => e
      errors << { "batch" => "content", "message" => "#{e.class}: #{e.message}" }
      raise SeedError, "reference content load failed: #{e.class}: #{e.message}"
    end
  end

  (start_index...end_index).each_slice(batch_size) do |household_indices|
    transaction_bundle_count += 1
    resources = []

    household_indices.each do |household_index|
      unless organization_emitted
        resources << organization_resource
        organization_emitted = true
      end

      # emitted_*_indices are per-invocation (per-shard), not global: a
      # catchment straddling a shard boundary is PUT once by each shard that
      # touches it. That is idempotent-safe (identical content) and avoids
      # cross-shard coordination; it can inflate the *reported* counts for
      # Location/Practitioner/PractitionerRole/CareTeam/Organization when
      # shard metadata are summed, but never the resources on the server, and
      # never the household-owned types, which exactly one shard generates.
      chw_index = chw_index_for(household_index)
      unit_index = unit_index_for(chw_index)
      catchment = catchment_for(unit_index, content, seed, catchment_cache)
      unless emitted_unit_indices.include?(unit_index)
        resources.concat(catchment_resources(catchment))
        emitted_unit_indices << unit_index
      end
      unless emitted_chw_indices.include?(chw_index)
        resources.concat(chw_resources(chw_index, catchment, seed))
        emitted_chw_indices << chw_index
      end

      resources.concat(resources_for_household(household_index, individuals_per_household, content, seed, options[:include_specimen], catchment_cache))
    end

    resources.each { |resource| resource_counts[resource["resourceType"]] += 1 }
    entries = resources.map { |resource| put_entry(resource) }
    progress_done = household_indices.last + 1 - start_index
    progress_total = end_index - start_index

    if metadata_only
      imported_entry_count += entries.length
      last_reported_percent = report_progress("Would import", progress_done, progress_total, shard_index, shard_count, last_reported_percent)
      next
    end

    bundle = { "resourceType" => "Bundle", "type" => "transaction", "entry" => entries }
    response = post_bundle_with_retries(uri, bundle, timeout, max_retries)
    record_response.call(response, entries, transaction_bundle_count, true)
    last_reported_percent = report_progress("Imported", progress_done, progress_total, shard_index, shard_count, last_reported_percent)
  rescue StandardError => e
    errors << { "batch" => transaction_bundle_count, "message" => "#{e.class}: #{e.message}" }
  end

  completed_at = Time.now.utc
  generated_entry_count = resource_counts.values.sum
  metadata = {
    "run_id" => run_id,
    "echis" => {
      "households" => households,
      "individuals_per_household" => individuals_per_household,
      "patients" => total_individuals(households, individuals_per_household),
      "seed" => seed,
      "generator" => "echis_seed",
      "data_model" => "echis-dev-aligned",
      "content_source" => File.basename(options[:content]),
      "content_resource_count" => content.resources.length,
      "shard_index" => shard_index,
      "shard_count" => shard_count,
      "start_index" => start_index,
      "end_index" => end_index,
      "transaction_bundle_count" => transaction_bundle_count,
      "generated_entry_count" => generated_entry_count,
      "resource_counts" => resource_counts.sort.to_h
    },
    "import" => {
      "mode" => metadata_only ? "metadata-only" : "transaction-load",
      "fhir_base_url" => metadata_only ? nil : fhir_base_url,
      "started_at_utc" => started_at.iso8601,
      "completed_at_utc" => completed_at.iso8601,
      "duration_seconds" => (completed_at - started_at).round(3),
      "http_status_counts" => http_status_counts.sort.to_h,
      "fhir_response_status_counts" => fhir_response_status_counts.sort.to_h,
      "submitted_entry_count" => generated_entry_count,
      "imported_entry_count" => imported_entry_count,
      "error_count" => errors.length,
      "errors" => errors
    },
    "created_at_utc" => started_at.iso8601,
    "completed_at_utc" => completed_at.iso8601
  }

  FileUtils.mkdir_p(File.dirname(metadata_path))
  File.write(metadata_path, "#{JSON.pretty_generate(metadata)}\n")

  unless errors.empty?
    warn "eCHIS seed failed with #{errors.length} error(s); see #{metadata_path}"
    exit 1
  end

  puts "Wrote eCHIS dataset metadata to #{metadata_path}"
  puts "#{metadata_only ? "Would import" : "Imported"} #{imported_entry_count} resource entries#{metadata_only ? "" : " into #{fhir_base_url}"}."
rescue SeedError => e
  warn "scripts/echis_seed.rb: #{e.message}"
  exit 1
end
